<script setup lang="ts">
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import EmptyState from '../../../components/admin/EmptyState.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import StatusBadge from '../../../components/admin/StatusBadge.vue';
import FieldError from '../../../components/FieldError.vue';
import StatusNotice from '../../../components/StatusNotice.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface Address { recipient_name: string | null; phone: string | null; country_code: string | null; region: string | null; city: string | null; district: string | null; address_line_1: string | null; address_line_2: string | null; postal_code: string | null; reference: string | null }
interface SavedAddress extends Address { id: string; label: string | null }
interface Allocation { location: string; code: string; quantity: number; status: string }
interface Line { id: string; product_name: string; variant_name: string | null; sku: string; quantity: number; base_unit_price: string; discount_unit_amount: string; final_unit_price: string; line_base_total: string; line_discount_total: string; line_total: string; promotion_name: string | null; tax_category_code: string | null; tax_rate: string | null; taxable_amount: string | null; exempt_amount: string | null; unaffected_amount: string | null; tax_amount: string | null; allocations: Allocation[] }
interface Checkout { id: string; token_hint: string; cart_id: string; status: string; delivery_type: string; currency: string | null; customer_name: string | null; email: string | null; phone: string | null; shipping: Address; billing: Address; subtotal_before_discounts: string; discount_total: string; subtotal: string; shipping_total: string; tax_total: string; taxable_amount: string | null; exempt_amount: string | null; unaffected_amount: string | null; tax_calculated_at: string | null; grand_total: string; expires_at: string | null; created_at: string; order: { id: string; order_number: string } | null; lines: Line[] }
interface CheckoutForm extends Record<string, string | boolean> { customer_name: string; email: string; phone: string; delivery_type: string; shipping_address_id: string; billing_address_id: string; billing_same_as_shipping: boolean; shipping_recipient_name: string; shipping_phone: string; shipping_country_code: string; shipping_region: string; shipping_city: string; shipping_district: string; shipping_address_line_1: string; shipping_address_line_2: string; shipping_postal_code: string; shipping_reference: string; billing_recipient_name: string; billing_phone: string; billing_country_code: string; billing_region: string; billing_city: string; billing_district: string; billing_address_line_1: string; billing_address_line_2: string; billing_postal_code: string; billing_reference: string }

const props = defineProps<{ checkout: Checkout; addresses: SavedAddress[]; canManage: boolean; canCreateOrder: boolean }>();
const page = usePage<PageProps>();
const { t, locale } = useI18n();
const serverErrors = computed(() => (page.props.errors ?? {}) as Record<string, string | undefined>);
const pending = computed(() => props.checkout.status === 'PENDING');
const ready = computed(() => props.checkout.status === 'READY');
const cancellable = computed(() => ['PENDING', 'READY'].includes(props.checkout.status));
const canViewOrder = computed(() => page.props.currentTenantMembership?.permissions.includes('orders.view') ?? false);
const editable = computed(() => pending.value && props.canManage);
const form = useForm<CheckoutForm>({
    customer_name: props.checkout.customer_name ?? '', email: props.checkout.email ?? '', phone: props.checkout.phone ?? '', delivery_type: props.checkout.delivery_type,
    shipping_address_id: '', billing_address_id: '', billing_same_as_shipping: false,
    shipping_recipient_name: props.checkout.shipping.recipient_name ?? '', shipping_phone: props.checkout.shipping.phone ?? '', shipping_country_code: props.checkout.shipping.country_code ?? '', shipping_region: props.checkout.shipping.region ?? '', shipping_city: props.checkout.shipping.city ?? '', shipping_district: props.checkout.shipping.district ?? '', shipping_address_line_1: props.checkout.shipping.address_line_1 ?? '', shipping_address_line_2: props.checkout.shipping.address_line_2 ?? '', shipping_postal_code: props.checkout.shipping.postal_code ?? '', shipping_reference: props.checkout.shipping.reference ?? '',
    billing_recipient_name: props.checkout.billing.recipient_name ?? '', billing_phone: props.checkout.billing.phone ?? '', billing_country_code: props.checkout.billing.country_code ?? '', billing_region: props.checkout.billing.region ?? '', billing_city: props.checkout.billing.city ?? '', billing_district: props.checkout.billing.district ?? '', billing_address_line_1: props.checkout.billing.address_line_1 ?? '', billing_address_line_2: props.checkout.billing.address_line_2 ?? '', billing_postal_code: props.checkout.billing.postal_code ?? '', billing_reference: props.checkout.billing.reference ?? '',
});
const prepareForm = useForm({});
const cancelForm = useForm({});
const orderForm = useForm({});
const addressFields: { key: keyof Address; label: string; autocomplete: string; max: number }[] = [
    { key: 'recipient_name', label: 'recipient', autocomplete: 'name', max: 160 }, { key: 'phone', label: 'phone', autocomplete: 'tel', max: 32 }, { key: 'country_code', label: 'country', autocomplete: 'country', max: 2 }, { key: 'region', label: 'region', autocomplete: 'address-level1', max: 255 }, { key: 'city', label: 'city', autocomplete: 'address-level2', max: 255 }, { key: 'district', label: 'district', autocomplete: 'address-level3', max: 255 }, { key: 'address_line_1', label: 'addressLine1', autocomplete: 'address-line1', max: 255 }, { key: 'address_line_2', label: 'addressLine2', autocomplete: 'address-line2', max: 255 }, { key: 'postal_code', label: 'postalCode', autocomplete: 'postal-code', max: 32 }, { key: 'reference', label: 'reference', autocomplete: 'off', max: 255 },
];
const localizedStatus = computed(() => {
    const keys: Record<string, string> = { 'Checkout started. Add contact details and prepare it when ready.': 'checkout.notices.started', 'Checkout details updated.': 'checkout.notices.updated', 'Checkout prepared and inventory reserved.': 'checkout.notices.prepared', 'Checkout cancelled and active reservations released.': 'checkout.notices.cancelled' };
    return page.props.status ? t(keys[page.props.status] ?? 'checkout.notices.completed') : undefined;
});
const operationError = computed(() => {
    for (const key of ['contact', 'shipping', 'cart', 'tax', 'inventory', 'checkout']) if (serverErrors.value[key]) return t(`checkout.errors.${key}`);
    return undefined;
});
const totals = computed(() => [
    ['beforeDiscounts', props.checkout.subtotal_before_discounts], ['discount', props.checkout.discount_total], ['taxable', props.checkout.taxable_amount ?? '0.0000'], ['exempt', props.checkout.exempt_amount ?? '0.0000'], ['unaffected', props.checkout.unaffected_amount ?? '0.0000'], ['taxIncluded', props.checkout.tax_total], ['subtotal', props.checkout.subtotal], ['shippingTotal', props.checkout.shipping_total], ['grandTotal', props.checkout.grand_total],
] as const);

const fieldName = (type: 'shipping' | 'billing', key: keyof Address) => `${type}_${key}` as keyof CheckoutForm;
const fieldError = (name: keyof CheckoutForm) => form.errors[name] ? t(`checkout.errors.${String(name).replace(/^shipping_|^billing_/u, 'address_')}`) : undefined;
const savedAddress = (id: string) => props.addresses.find((address) => address.id === id);
const addressLines = (address: Address | undefined): string[] => address ? [address.recipient_name, address.phone, address.address_line_1, address.address_line_2, [address.district, address.city, address.region].filter(Boolean).join(', '), [address.country_code, address.postal_code].filter(Boolean).join(' '), address.reference].filter((line): line is string => Boolean(line)) : [];
const hasAddress = (address: Address) => addressLines(address).length > 0;
const formatDate = (value: string | null) => value ? new Intl.DateTimeFormat(locale.value, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : t('checkout.notSet');
const money = (amount: string | null) => amount === null ? t('common.unavailable') : `${props.checkout.currency ?? ''} ${amount}`.trim();
const discountMoney = (amount: string) => `${props.checkout.currency ?? ''} -${amount}`.trim();
const save = () => { if (!form.processing) form.patch(`/admin/checkouts/${props.checkout.id}`, { preserveScroll: true, onSuccess: () => form.defaults() }); };
const prepare = () => { if (!prepareForm.processing && !form.isDirty) prepareForm.post(`/admin/checkouts/${props.checkout.id}/prepare`, { preserveScroll: true }); };
const cancel = () => { if (!cancelForm.processing && window.confirm(t('checkout.cancelConfirm'))) cancelForm.post(`/admin/checkouts/${props.checkout.id}/cancel`, { preserveScroll: true }); };
const createOrder = () => { if (!orderForm.processing && window.confirm(t('checkout.orderConfirm'))) orderForm.post(`/admin/checkouts/${props.checkout.id}/order`, { preserveScroll: true }); };
</script>

<template>
    <Head :title="t('checkout.detailTitle', { token: checkout.token_hint })" />
    <AdminLayout>
        <section class="mx-auto grid w-full max-w-[90rem] gap-5 sm:gap-6">
            <Breadcrumbs :items="[{ label: t('nav.sales') }, { label: t('checkout.title'), href: '/admin/checkouts' }, { label: checkout.token_hint }]" />
            <PageHeader :title="t('checkout.detailTitle', { token: checkout.token_hint })" :eyebrow="t('common.currentStore')" :description="t('checkout.detailDescription')"><template #actions><div class="flex flex-col gap-2 sm:flex-row sm:flex-wrap sm:justify-end"><Link v-if="checkout.order && canViewOrder" :href="`/admin/orders/${checkout.order.id}`" class="inline-flex min-h-9 items-center justify-center rounded-md bg-admin-primary px-4 text-sm font-semibold text-white">{{ t('checkout.openOrder', { number: checkout.order.order_number }) }}</Link><span v-else-if="checkout.order" class="inline-flex min-h-9 items-center rounded-md border border-admin-border bg-admin-canvas px-4 font-mono text-xs font-semibold">{{ checkout.order.order_number }}</span><button v-else-if="canCreateOrder && ready" type="button" :disabled="orderForm.processing" class="min-h-9 rounded-md bg-admin-primary px-4 text-sm font-semibold text-white disabled:opacity-60" @click="createOrder">{{ orderForm.processing ? t('checkout.creatingOrder') : t('checkout.createOrder') }}</button><button v-if="canManage && cancellable" type="button" :disabled="cancelForm.processing" class="min-h-9 rounded-md border border-admin-danger-border bg-white px-4 text-sm font-semibold text-admin-danger disabled:opacity-60" @click="cancel">{{ cancelForm.processing ? t('checkout.cancelling') : t('checkout.cancelCheckout') }}</button><Link href="/admin/checkouts" class="inline-flex min-h-9 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary">{{ t('checkout.back') }}</Link></div></template></PageHeader>
            <StatusNotice :message="localizedStatus" class="!mb-0 rounded-md !border-admin-success !bg-admin-success-bg !text-admin-success" />
            <aside v-if="operationError" class="rounded-md border border-admin-danger-border bg-admin-danger-bg px-4 py-3"><FieldError :message="operationError" /></aside>
            <aside v-if="!editable" class="rounded-md border px-4 py-3" :class="ready ? 'border-admin-info-border bg-admin-info-bg' : 'border-admin-border bg-admin-surface'"><p class="text-sm font-semibold text-admin-text">{{ ready ? t('checkout.readyTitle') : t('checkout.readOnlyTitle') }}</p><p class="mt-0.5 text-xs text-admin-text-secondary">{{ ready ? t('checkout.readyHelp') : t('checkout.readOnlyHelp') }}</p></aside>

            <div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article class="admin-card p-4"><p class="admin-label">{{ t('common.status') }}</p><p class="mt-2"><StatusBadge :status="checkout.status" /></p><p class="mt-2 text-xs text-admin-neutral">{{ t(`checkout.delivery.${checkout.delivery_type}`) }}</p></article><article class="admin-card p-4"><p class="admin-label">{{ t('checkout.customer') }}</p><p class="mt-2 truncate text-sm font-semibold">{{ checkout.customer_name || t('checkout.guest') }}</p><p class="mt-1 truncate text-xs text-admin-neutral">{{ checkout.email || checkout.phone || t('checkout.noContact') }}</p></article><article class="admin-card p-4"><p class="admin-label">{{ t('checkout.created') }}</p><p class="mt-2 text-xs font-semibold">{{ formatDate(checkout.created_at) }}</p></article><article class="admin-card p-4"><p class="admin-label">{{ t('checkout.expires') }}</p><p class="mt-2 text-xs font-semibold">{{ formatDate(checkout.expires_at) }}</p><p v-if="ready" class="mt-1 text-[10px] text-admin-neutral">{{ t('checkout.reservationExpiryHelp') }}</p></article></div>

            <form v-if="editable" class="grid gap-5" @submit.prevent="save">
                <section class="admin-card overflow-hidden"><header class="border-b border-admin-border px-5 py-4 sm:px-6"><p class="admin-label text-admin-secondary">{{ t('checkout.contactSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('checkout.contact') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('checkout.contactHelp') }}</p></header><div class="grid gap-4 p-5 sm:p-6 md:grid-cols-3"><div><label for="checkout-name" class="mb-1.5 block text-sm font-semibold">{{ t('checkout.name') }}</label><input id="checkout-name" v-model="form.customer_name" maxlength="160" autocomplete="name" class="admin-control w-full px-3 text-sm" :aria-invalid="Boolean(form.errors.customer_name)" /><FieldError :message="fieldError('customer_name')" /></div><div><label for="checkout-email" class="mb-1.5 block text-sm font-semibold">{{ t('checkout.email') }}</label><input id="checkout-email" v-model="form.email" type="email" maxlength="254" autocomplete="email" class="admin-control w-full px-3 text-sm" :aria-invalid="Boolean(form.errors.email)" /><FieldError :message="fieldError('email')" /></div><div><label for="checkout-phone" class="mb-1.5 block text-sm font-semibold">{{ t('checkout.phone') }}</label><input id="checkout-phone" v-model="form.phone" type="tel" maxlength="31" autocomplete="tel" class="admin-control w-full px-3 text-sm" :aria-invalid="Boolean(form.errors.phone)" /><FieldError :message="fieldError('phone')" /></div></div></section>

                <section class="admin-card overflow-hidden"><header class="border-b border-admin-border px-5 py-4 sm:px-6"><p class="admin-label text-admin-secondary">{{ t('checkout.deliverySection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('checkout.deliveryTitle') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('checkout.deliveryHelp') }}</p></header><div class="p-5 sm:p-6"><fieldset><legend class="text-sm font-semibold">{{ t('checkout.deliveryType') }}</legend><div class="mt-3 grid gap-2 sm:grid-cols-2"><label v-for="value in ['SHIPPING', 'PICKUP']" :key="value" class="flex cursor-pointer items-start gap-3 rounded-md border p-3" :class="form.delivery_type === value ? 'border-admin-secondary bg-admin-info-bg' : 'border-admin-border bg-white'"><input v-model="form.delivery_type" type="radio" :value="value" class="mt-0.5 size-4" /><span><span class="block text-sm font-semibold">{{ t(`checkout.delivery.${value}`) }}</span><span class="mt-0.5 block text-xs text-admin-neutral">{{ t(`checkout.delivery.${value}Help`) }}</span></span></label></div></fieldset><FieldError :message="fieldError('delivery_type')" /></div>
                    <div v-if="form.delivery_type === 'SHIPPING'" class="grid gap-5 border-t border-admin-border p-5 sm:p-6 lg:grid-cols-2"><fieldset class="min-w-0"><legend class="text-sm font-semibold">{{ t('checkout.shippingAddress') }}</legend><p class="mt-1 text-xs text-admin-neutral">{{ t('checkout.shippingRequired') }}</p><label v-if="addresses.length" for="shipping-saved" class="mt-4 block"><span class="admin-label">{{ t('checkout.savedAddress') }}</span><select id="shipping-saved" v-model="form.shipping_address_id" class="admin-control mt-1.5 w-full px-3 text-sm"><option value="">{{ t('checkout.manualAddress') }}</option><option v-for="address in addresses" :key="address.id" :value="address.id">{{ address.label || address.address_line_1 }}</option></select></label><address v-if="form.shipping_address_id" class="mt-3 rounded-md border border-admin-border bg-admin-canvas p-3 text-xs leading-5 not-italic text-admin-text-secondary"><span v-for="line in addressLines(savedAddress(form.shipping_address_id))" :key="line" class="block">{{ line }}</span></address><div v-else class="mt-4 grid gap-3 sm:grid-cols-2"><div v-for="field in addressFields" :key="`shipping-${field.key}`" :class="['address_line_1', 'address_line_2', 'reference'].includes(field.key) ? 'sm:col-span-2' : ''"><label :for="`shipping-${field.key}`" class="mb-1.5 block text-xs font-semibold">{{ t(`checkout.address.${field.label}`) }}</label><input :id="`shipping-${field.key}`" v-model="form[fieldName('shipping', field.key)]" :maxlength="field.max" :autocomplete="field.autocomplete" class="admin-control w-full px-3 text-sm" :class="field.key === 'country_code' ? 'uppercase' : ''" :aria-invalid="Boolean(form.errors[fieldName('shipping', field.key)])" /><FieldError :message="fieldError(fieldName('shipping', field.key))" /></div></div></fieldset>
                        <fieldset class="min-w-0"><legend class="text-sm font-semibold">{{ t('checkout.billingAddress') }}</legend><label class="mt-3 flex items-center gap-2 text-sm"><input v-model="form.billing_same_as_shipping" type="checkbox" class="size-4" /><span>{{ t('checkout.sameAsShipping') }}</span></label><template v-if="!form.billing_same_as_shipping"><label v-if="addresses.length" for="billing-saved" class="mt-4 block"><span class="admin-label">{{ t('checkout.savedAddress') }}</span><select id="billing-saved" v-model="form.billing_address_id" class="admin-control mt-1.5 w-full px-3 text-sm"><option value="">{{ t('checkout.manualOrEmpty') }}</option><option v-for="address in addresses" :key="address.id" :value="address.id">{{ address.label || address.address_line_1 }}</option></select></label><address v-if="form.billing_address_id" class="mt-3 rounded-md border border-admin-border bg-admin-canvas p-3 text-xs leading-5 not-italic text-admin-text-secondary"><span v-for="line in addressLines(savedAddress(form.billing_address_id))" :key="line" class="block">{{ line }}</span></address><div v-else class="mt-4 grid gap-3 sm:grid-cols-2"><div v-for="field in addressFields" :key="`billing-${field.key}`" :class="['address_line_1', 'address_line_2', 'reference'].includes(field.key) ? 'sm:col-span-2' : ''"><label :for="`billing-${field.key}`" class="mb-1.5 block text-xs font-semibold">{{ t(`checkout.address.${field.label}`) }}</label><input :id="`billing-${field.key}`" v-model="form[fieldName('billing', field.key)]" :maxlength="field.max" :autocomplete="field.autocomplete" class="admin-control w-full px-3 text-sm" :class="field.key === 'country_code' ? 'uppercase' : ''" :aria-invalid="Boolean(form.errors[fieldName('billing', field.key)])" /><FieldError :message="fieldError(fieldName('billing', field.key))" /></div></div></template></fieldset></div>
                </section>
                <footer class="flex flex-col gap-3 rounded-md border border-admin-border bg-admin-canvas p-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="text-sm font-semibold">{{ t('checkout.prepareTitle') }}</p><p class="mt-0.5 text-xs text-admin-neutral">{{ form.isDirty ? t('checkout.saveBeforePrepare') : t('checkout.prepareHelp') }}</p></div><div class="flex flex-col-reverse gap-2 sm:flex-row"><button type="submit" :disabled="form.processing || prepareForm.processing" class="min-h-10 rounded-md border border-admin-border-strong bg-white px-5 text-sm font-semibold text-admin-text-secondary disabled:opacity-60">{{ form.processing ? t('common.saving') : t('checkout.saveDetails') }}</button><button type="button" :disabled="form.processing || prepareForm.processing || form.isDirty" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-50" @click="prepare">{{ prepareForm.processing ? t('checkout.preparing') : t('checkout.prepare') }}</button></div></footer>
            </form>

            <section v-else class="grid gap-3 lg:grid-cols-3"><article class="admin-card p-4 sm:p-5"><h2 class="text-sm font-semibold">{{ t('checkout.contactSnapshot') }}</h2><dl class="mt-4 grid gap-3 text-sm"><div><dt class="admin-label">{{ t('checkout.name') }}</dt><dd class="mt-1">{{ checkout.customer_name || t('common.none') }}</dd></div><div><dt class="admin-label">{{ t('checkout.email') }}</dt><dd class="mt-1 break-words">{{ checkout.email || t('common.none') }}</dd></div><div><dt class="admin-label">{{ t('checkout.phone') }}</dt><dd class="mt-1 font-mono text-xs">{{ checkout.phone || t('common.none') }}</dd></div></dl></article><article v-if="checkout.delivery_type === 'SHIPPING'" class="admin-card p-4 sm:p-5"><h2 class="text-sm font-semibold">{{ t('checkout.shippingSnapshot') }}</h2><address v-if="hasAddress(checkout.shipping)" class="mt-4 text-xs leading-5 not-italic text-admin-text-secondary"><span v-for="line in addressLines(checkout.shipping)" :key="line" class="block">{{ line }}</span></address><p v-else class="mt-4 text-xs text-admin-neutral">{{ t('checkout.notProvided') }}</p></article><article class="admin-card p-4 sm:p-5"><h2 class="text-sm font-semibold">{{ t('checkout.billingSnapshot') }}</h2><address v-if="hasAddress(checkout.billing)" class="mt-4 text-xs leading-5 not-italic text-admin-text-secondary"><span v-for="line in addressLines(checkout.billing)" :key="line" class="block">{{ line }}</span></address><p v-else class="mt-4 text-xs text-admin-neutral">{{ t('checkout.notProvided') }}</p></article></section>

            <section><div class="mb-3"><p class="admin-label text-admin-secondary">{{ t('checkout.totalsSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('checkout.commercialTotals') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('checkout.taxInclusiveHelp') }}</p></div><div class="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-5"><article v-for="item in totals" :key="item[0]" class="admin-card min-w-0 p-3 sm:p-4" :class="item[0] === 'grandTotal' ? 'border-admin-primary' : ''"><p class="admin-label truncate">{{ t(`checkout.totals.${item[0]}`) }}</p><p class="mt-2 truncate font-mono text-xs font-semibold tabular-nums sm:text-sm" :class="item[0] === 'grandTotal' ? 'text-admin-primary' : ''">{{ item[0] === 'discount' ? discountMoney(item[1]) : money(item[1]) }}</p></article></div><p v-if="checkout.tax_calculated_at" class="mt-2 text-[10px] text-admin-neutral">{{ t('checkout.taxCalculated', { date: formatDate(checkout.tax_calculated_at) }) }}</p></section>

            <section><div class="mb-3"><p class="admin-label text-admin-secondary">{{ t('checkout.linesSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('checkout.snapshotLines') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('checkout.linesHelp') }}</p></div><div v-if="checkout.lines.length" class="grid gap-3"><article v-for="line in checkout.lines" :key="line.id" class="admin-card p-4 sm:p-5"><div class="grid gap-5 lg:grid-cols-[minmax(0,1.2fr)_minmax(20rem,1fr)]"><div class="min-w-0"><h3 class="truncate text-sm font-semibold">{{ line.product_name }}</h3><p class="mt-1 truncate text-xs text-admin-text-secondary">{{ line.variant_name || t('checkout.defaultVariant') }} · <span class="font-mono">{{ line.sku }}</span></p><p class="mt-2 text-xs text-admin-neutral">{{ t('checkout.quantity') }}: <strong class="font-mono text-admin-text">{{ line.quantity }}</strong></p><span v-if="line.promotion_name" class="mt-3 inline-flex rounded border border-admin-success-border bg-admin-success-bg px-2 py-1 text-[10px] font-semibold text-admin-success">{{ line.promotion_name }}</span><p v-if="line.tax_category_code" class="mt-3 font-mono text-[10px] text-admin-neutral">{{ line.tax_category_code }} · {{ line.tax_rate }}% · {{ t('checkout.tax') }} {{ money(line.tax_amount) }}</p></div><dl class="grid grid-cols-2 gap-x-4 gap-y-3 text-xs sm:grid-cols-3"><div><dt class="admin-label">{{ t('checkout.baseUnit') }}</dt><dd class="mt-1 font-mono">{{ money(line.base_unit_price) }}</dd></div><div><dt class="admin-label">{{ t('checkout.unitDiscount') }}</dt><dd class="mt-1 font-mono">{{ discountMoney(line.discount_unit_amount) }}</dd></div><div><dt class="admin-label">{{ t('checkout.finalUnit') }}</dt><dd class="mt-1 font-mono">{{ money(line.final_unit_price) }}</dd></div><div><dt class="admin-label">{{ t('checkout.lineBase') }}</dt><dd class="mt-1 font-mono">{{ money(line.line_base_total) }}</dd></div><div><dt class="admin-label">{{ t('checkout.lineDiscount') }}</dt><dd class="mt-1 font-mono">{{ discountMoney(line.line_discount_total) }}</dd></div><div><dt class="admin-label">{{ t('checkout.lineTotal') }}</dt><dd class="mt-1 font-mono font-semibold">{{ money(line.line_total) }}</dd></div><div><dt class="admin-label">{{ t('checkout.taxable') }}</dt><dd class="mt-1 font-mono">{{ money(line.taxable_amount) }}</dd></div><div><dt class="admin-label">{{ t('checkout.exempt') }}</dt><dd class="mt-1 font-mono">{{ money(line.exempt_amount) }}</dd></div><div><dt class="admin-label">{{ t('checkout.unaffected') }}</dt><dd class="mt-1 font-mono">{{ money(line.unaffected_amount) }}</dd></div></dl></div><div v-if="line.allocations.length" class="mt-4 border-t border-admin-border pt-3"><p class="admin-label">{{ t('checkout.reservations') }}</p><div class="mt-2 flex flex-wrap gap-2"><span v-for="allocation in line.allocations" :key="`${allocation.code}-${allocation.status}`" class="inline-flex items-center gap-2 rounded border border-admin-border bg-admin-canvas px-2.5 py-1 text-[10px]"><span class="font-semibold">{{ allocation.code }}</span><span class="font-mono">{{ allocation.quantity }}</span><StatusBadge :status="allocation.status" /></span></div></div></article></div><EmptyState v-else :title="t('checkout.noLines')" :description="pending ? t('checkout.noLinesPendingHelp') : t('checkout.noLinesHelp')" /></section>
        </section>
    </AdminLayout>
</template>
